<?php require_once 'includes/db.php'; $pageTitle='Relatórios'; require 'includes/header.php'; $data=$_GET['data']??date('Y-m-d'); ?><div class="page-heading"><div><h1 class="h3 mb-1">Relatório de fretes</h1><p class="text-secondary mb-0">Selecione um dia para consultar e baixar os registros.</p></div></div><form class="card p-3 mb-3" method="get"><div class="row align-items-end"><div class="col-md-4"><label class="form-label">Data</label><input class="form-control" type="date" name="data" value="<?=e($data)?>" required></div><div class="col-md-3"><button class="btn btn-primary">Consultar</button></div><div class="col-md-5 text-md-end"><a class="btn btn-outline-success" href="relatorio_csv.php?data=<?=urlencode($data)?>">Baixar relatório CSV</a></div></div></form><?php $s=$pdo->prepare("SELECT f.codigo,f.data_frete,f.status,o.identificacao origem,d.identificacao destino,t.nome transportador,GROUP_CONCAT(CONCAT(p.nome,' (',fp.quantidade,')') SEPARATOR '; ') produtos FROM fretes f JOIN enderecos o ON o.id=f.origem_id JOIN enderecos d ON d.id=f.destino_id JOIN transportadores t ON t.id=f.transportador_id JOIN frete_produtos fp ON fp.frete_id=f.id JOIN produtos p ON p.id=fp.produto_id WHERE f.data_frete=? GROUP BY f.id ORDER BY f.codigo");$s->execute([$data]);$rows=$s->fetchAll(); ?><div class="card p-3"><h2 class="h5">Resultados de <?=date('d/m/Y',strtotime($data))?></h2><div class="table-responsive"><table class="table"><thead><tr><th>Código</th><th>Origem → Destino</th><th>Transportador</th><th>Produtos</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['codigo'])?></td><td><?=e($r['origem'].' → '.$r['destino'])?></td><td><?=e($r['transportador'])?></td><td><?=e($r['produtos'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="5" class="text-center text-secondary">Não há fretes para a data selecionada.</td></tr><?php endif; ?></tbody></table></div></div><?php require 'includes/footer.php'; ?>
